mapper.select:
SELECT i.*, e.emp_no, e.name AS employee_name, d.name AS dept_name FROM hr_payroll_item i JOIN hr_employee e ON e.id = i.employee_id LEFT JOIN sys_dept d ON d.id = i.dept_id WHERE i.payroll_id = #{payrollId}
AND (e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.emp_no
